975	  private async loadPackets(runId: string, directory: FileHandle, registrations: PacketRegistration[]): Promise<LoadedPacket[]> {
976	    const keys = new Set<string>()
977	    const packets: LoadedPacket[] = []
978	    for (const registration of registrations) {
979	      const key = `${registration.phase}:${registration.node_id}:${registration.attempt}`
980	      if (keys.has(key)) throw invalidRun(runId, `duplicate verification packet registration ${key}`)
981	      keys.add(key)
982	      if (registration.path !== packetPath(registration)) throw invalidRun(runId, `verification packet ${key} is registered outside the run's verification directory`)
983	      let bytes: Buffer | null
984	      try {
985	        bytes = await readBounded(directory, registration.path.split('/'), this.options.packetByteLimit)
986	      } catch (error) {
987	        if (!(error instanceof ProjectApiError)) throw error
988	        packets.push({ ...registration, ok: false, reason: 'packet exceeds the read limit' })
989	        continue
990	      }
991	      if (bytes === null) { packets.push({ ...registration, ok: false, reason: 'packet file is missing or not a regular file' }); continue }
992	      if (sha256(bytes) !== registration.sha256) { packets.push({ ...registration, ok: false, reason: 'packet content does not match its registered hash' }); continue }
993	      let parsed: unknown
994	      try {
995	        parsed = JSON.parse(bytes.toString('utf8'))
996	      } catch {
997	        packets.push({ ...registration, ok: false, reason: 'packet is not valid JSON' })
998	        continue
999	      }
1000	      const packet = packetSchema.safeParse(parsed)
1001	      if (!packet.success) { packets.push({ ...registration, ok: false, reason: `packet ${issueText(packet.error)}` }); continue }
1002	      if (packet.data.phase !== registration.phase) { packets.push({ ...registration, ok: false, reason: 'packet phase differs from its registration' }); continue }
1003	      const deferredIds = new Set(packet.data.gate.deferred_checks ?? [])
1004	      const deferred = (packet.data.evidence?.checks ?? []).filter(check => deferredIds.has(check.id)).map(check => ({ id: check.id, check_index: check.worker_check_index }))
1005	      packets.push({ ...registration, ok: true, gate: packet.data.gate, result: packet.data.result, deferred })
1006	    }
1007	    return packets
1008	  }
