1215	/** Publishes a verified packet's result: scoped artifact links, no worktree paths, and a failed status when the gate did not pass. */
1216	function projectWorkerResult(scope: Scope, runId: string, nodeId: string, packet: LoadedPacket & { ok: true }): WorkerResult {
1217	  const raw = packet.result
1218	  if (raw.run_id !== runId || raw.node_id !== packet.node_id || raw.attempt !== packet.attempt) {
1219	    throw new ProjectApiError(500, 'EVIDENCE_MISMATCH', 'The verification packet result does not match its registration.')
1220	  }
1221	  const passed = packet.gate.status === 'passed'
1222	  const checks = Array.isArray(raw.checks) ? (raw.checks as Record<string, unknown>[]).map(check => ({ ...check, cwd: `verification/${packet.phase}/${packet.node_id}/${packet.attempt}/worktree` })) : raw.checks
1223	  const artifacts = Array.isArray(raw.artifacts) ? (raw.artifacts as Record<string, unknown>[]).map(artifact => ({
1224	    ...artifact, uri: typeof artifact.artifact_id === 'string' ? `${runRoute(scope, runId)}/artifacts/${encodeURIComponent(artifact.artifact_id)}` : artifact.uri,
1225	  })) : raw.artifacts
1226	  const assumptions = Array.isArray(raw.open_assumptions) ? raw.open_assumptions.filter(item => typeof item === 'string' && item.trim().length > 0) : raw.open_assumptions
1227	  const candidate = {
1228	    contract_version: '1.0.0', run_id: runId, node_id: nodeId, attempt: packet.attempt, session_id: raw.session_id,
1229	    status: passed ? raw.status : 'failed', base_commit: raw.base_commit, output_commit: raw.output_commit,
1230	    changed_files: raw.changed_files, checks, open_assumptions: assumptions, artifacts,
1231	    ...(packet.deferred.length > 0 ? { deferred_checks: packet.deferred } : {}),
1232	    // Worker-phase captures list the changed paths not copied as `file` artifacts; older and candidate-phase results carry none.
1233	    ...(raw.files_not_captured !== undefined ? { files_not_captured: raw.files_not_captured } : {}),
1234	    summary: typeof raw.summary === 'string' ? redactPaths(raw.summary) : raw.summary,
1235	    error: passed ? raw.error : { code: 'VERIFICATION_BLOCKED', message: redactPaths(packet.gate.reasons.join('; ')) || 'Verification did not pass.', retryable: true },
1236	  }
1237	  try {
1238	    return validateWorkerResult(candidate)
1239	  } catch (error) {
1240	    throw new ProjectApiError(500, 'RESULT_INVALID', `The verification packet result does not conform to the worker result contract: ${error instanceof z.ZodError ? issueText(error) : (error as Error).message}`)
1241	  }
